import json,datetime
from pathlib import Path
from wsp.metrics import normalise
from wsp.pages import page_loop
s=json.loads(Path('state.json').read_text()); a=s['baseline_lines']; b=s['kept_lines']; d=[y[0]-x[0] for x,y in zip(a,b)]; i=d.index(min(d)); print('pages improved,worse,tied',sum(t<0 for t in d),sum(t>0 for t in d),d.count(0),'min',min(d),'loo',(sum(d)-min(d))/(sum(c for e,c in a)-a[i][1]))
def rows(f):return {Path(x['image']).stem:x for x in map(json.loads,Path(f).read_text().splitlines())}
r=rows('passes/pass-001.draw.jsonl'); p=[rows(f'passes/pass-00{i}.raw.jsonl') for i in (1,2)]; print('worst/best changes',sorted(zip(d,r))[:4], sorted(zip(d,r))[-4:]);
for test in (lambda v,k: v['at_cap'],lambda v,k:page_loop(normalise(v['raw']),normalise(r[k]['text']))):
 x,y=[{k for k,v in t.items() if test(v,k)} for t in p];print('resolved',sorted(x-y),'new',sorted(y-x),'remain',len(x&y))
print(datetime.datetime.now(datetime.timezone.utc))

